SOURCE_PLAYER = '我都先道歉'
SOURCE_EPISODE = 106180736
def act(observation, configuration):
    player = int(observation.get('player', 0))
    step = min(int(observation.get('step', 0)), len(ACTIONS) - 1)
    action = copy.deepcopy(ACTIONS[step])
    farms = observation.get('farms') or []
    hands = farms[player].get('hands') or [] if player < len(farms) else []
    action['hands'] = action.get('hands', [])[:len(hands)]
    return action
def agent(observation, configuration): return act(observation, configuration)
